 if(mode==='cycling'){if(taps.has('up'))l.lane=Math.max(0,l.lane-1);if(taps.has('down'))l.lane=Math.min(2,l.lane+1);l.progress+=dt*(c.kind==='cycle'?2.8:2.3)*speed;if(action){l.progress+=.5;l.stamina-=.45;}l.stamina=Math.min(max,l.stamina+dt*1.8);}
 if(mode==='cycling'||mode==='obstacle'){l.spawn-=dt;if(l.spawn<0){l.spawn=(save.difficulty==='cozy'?1.45:1.15)+(Math.sin(l.t*7)+1)*.35;l.obstacles.push({x:W+8,lane:Math.floor((Math.sin(l.t*15)+1)*1.49),kind:Math.floor(l.t)%3===0?'mud':'wall',hit:false});}for(const o of l.obstacles){o.x-=dt*65*speed;if(!o.hit&&Math.abs(o.x-W*.24)<9){if(mode==='cycling'&&o.lane===l.lane){hurt();o.hit=true;}else if(mode==='obstacle'){if(o.kind==='mud'){if(!keys.has('right')&&l.jump<8){hurt();l.progress-=1;}}else if(l.jump<20)hurt();o.hit=true;}}}l.obstacles=l.obstacles.filter(o=>o.x>-32);}
 if(mode==='desert'){const run=keys.has('right');l.progress+=dt*(run?3.2:1)*speed;l.heat=Math.max(0,l.heat+dt*(run?(c.kind==='cool'?2.2:3.1):-3));if(l.heat>78){l.stamina-=dt*8;feedback('TOO HOT! SIP / REST');}else l.stamina=Math.min(max,l.stamina+dt*.5);const well=Math.floor(l.progress/25);if(well>l.wells){l.wells=well;l.water=Math.min(6,l.water+2);feedback('WATER REFILLED');sound.fx('water');}}
