 const avoid=mode==='obstacle'?'jump':mode==='cycling'?'lane':'hop';if(avoid==='hop'&&taps.has('up')&&l.hopCd<=0){l.hop=.5;l.hopCd=.7;sound.fx('jump');}l.hop=Math.max(0,l.hop-dt);l.hopCd=Math.max(0,l.hopCd-dt);l.slow=Math.max(0,l.slow-dt);
 l.hazSpawn-=dt;if(l.hazSpawn<0&&l.progress<94){l.hazSpawn=(save.difficulty==='cozy'?3.3:2.5)+(Math.sin(l.t*11)+1)*.6;l.hazards.push({x:W+10,lane:Math.floor((Math.cos(l.t*9)+1)*1.49),done:false,hitRivals:l.rivals.map((_,i)=>(Math.sin(l.t*(5+i*3)+i)+1)/2<.38)});}
