function door(){codeBuffer='';codeCursor=0;codeShift=false;codeMessage='';if(save.unlock||save.patches.length===data.length){dialog={kind:'final',title:'22B: THE FINAL ROOM',body:'Gather twelve stars. Take them home to the kennel. Arrows move. A jumps. This room contains no private website content.'};change('finalintro');}else change('lock');}
const codeKeys=[...'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-_','DEL','SHF','OK','BACK'];
