// All canvas UI shares one hit map, independent of hidden semantic controls.
// Use the displayed canvas rect, not assumed integer scale (zoom/letterboxing can differ).
function canvasHit(e){const b=canvas.getBoundingClientRect();if(!b.width||!b.height)return null;const x=Math.floor((e.clientX-b.left)*canvas.width/b.width),y=Math.floor((e.clientY-b.top)*canvas.height/b.height);if(x<0||y<0||x>=canvas.width||y>=canvas.height)return null;return [...hits].reverse().find(h=>x>=h.x&&x<h.x+h.w&&y>=h.y&&y<h.y+h.h)||null;}
function activateHit(h){if(!h)return;sound.gesture();if(h.key){press(h.key);setTimeout(()=>release(h.key),70);}else h.fn();render();}
